'use strict';
const $=id=>document.getElementById(id),ctx=$('arena').getContext('2d'),keys=new Set();let battle,selected=null,last=0,signature='';
function reset(){let book=SkillSystem.grant(null,{id:'lab:source',ownerId:'taei',origin:'essence',name:'실험 전용 능력 · 본편 미지급',effects:['strike','bolt','guard','dash','mend'],elements:['arcane'],conditions:['none'],maxPower:2,maxRange:6,active:true,equipmentId:''});battle=new RealTimeBattle({skillBook:book,monsters:['goblin'],stats:{goblin:{hp:10000,name:'시험 표적'}}});const e=battle.units[1];e.x=6.5;e.y=8;e.speed=0;e.cooldown=1e6;selected=null;signature='';$('notice').textContent='실험을 초기화했습니다. 본편 스킬을 지급하지 않습니다.';}
function notice(fn){try{fn();}catch(e){$('notice').textContent=e.message;}}
$('reset').onclick=reset;
$('basic').onclick=()=>{if(!battle.paused)battle.startAttack(battle.units[0]);};
$('pause').onclick=()=>{battle.setPaused(!battle.paused);$('pause').textContent=battle.paused?'전투 재개':'일시정지';};
$('injury').onclick=()=>{if(battle.paused)return;$('notice').textContent='시험 표적에게 실제 피해 12를 받았습니다.';battle.damage(battle.units[1],battle.units[0],12);};
$('register').onclick=()=>notice(()=>{const p={ownerId:'taei',name:$('name').value,basisIds:['lab:source'],evidenceIds:battle.skillBook.practice.filter(e=>e.ownerId==='taei').slice(-3).map(e=>e.id),effect:$('effect').value,element:'arcane',power:2,range:$('effect').value==='bolt'?6:2,condition:'none',motif:$('motif').value};const result=SkillSystem.register(battle.skillBook,p,{era:'fantasy'});battle.skillBook=result.book;selected=result.skill.id;$('notice').textContent=result.created?'검증을 통과해 시험 스킬을 등록했습니다.':'같은 실행 정의가 이미 있어 기존 스킬을 선택했습니다.';});
$('cast').onclick=()=>{const r=battle.submitIntent({intent:'registered_skill',skillId:selected,targetId:battle.selected,opportunityId:null,when:'now'},'lab-'+Date.now());$('notice').textContent=r.ok?(r.planned?'재개 시 다시 검사합니다.':'준비 동작을 시작했습니다.'):r.error;};
addEventListener('keydown',e=>{if(e.target.matches('input,select'))return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Space'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.code==='Space'&&!e.repeat&&!battle.paused)battle.dodge(battle.units[0],0,1);});addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>keys.clear());
const point=u=>({x:100+u.x*26,y:40+u.y*25});
function frame(ms){const dt=last?Math.min(.05,(ms-last)/1000):0;last=ms;battle.step(dt,{x:Number(keys.has('ArrowRight')||keys.has('KeyD'))-Number(keys.has('ArrowLeft')||keys.has('KeyA')),y:Number(keys.has('ArrowDown')||keys.has('KeyS'))-Number(keys.has('ArrowUp')||keys.has('KeyW'))});ctx.clearRect(0,0,800,440);ctx.strokeStyle='#29424b';ctx.lineWidth=1;for(let x=0;x<800;x+=26){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,440);ctx.stroke();}for(let y=0;y<440;y+=25){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(800,y);ctx.stroke();}for(const e of battle.events)if(e.type==='skill_fx')SkillEffects.draw(ctx,e,point,26,battle.time-e.time,matchMedia('(prefers-reduced-motion:reduce)').matches);for(const u of battle.units){const p=point(u);ctx.fillStyle=u.team==='ally'?'#c3dfcb':'#d5ad8b';ctx.beginPath();ctx.arc(p.x,p.y,13,0,7);ctx.fill();ctx.strokeStyle='#f0ead5';if(u.action){ctx.beginPath();ctx.arc(p.x,p.y,20,0,Math.PI*2*(1-u.action.remaining/u.action.duration));ctx.stroke();}ctx.font='13px system-ui';ctx.textAlign='center';ctx.fillStyle='#f1f2ed';ctx.fillText(u.name,p.x,p.y+(u.team==='ally'?35:-27));}for(const shot of battle.projectiles){const p=point(shot);ctx.fillStyle='#b3caff';ctx.beginPath();ctx.arc(p.x,p.y,5,0,7);ctx.fill();}const p=battle.units[0];$('status').textContent='HP '+p.hp+'/'+p.max+' · MP '+p.mana.toFixed(1)+' · '+battle.time.toFixed(1)+'초';$('proof').textContent='실제 적중 경험 '+battle.skillBook.practice.length+'개 / 등록 필요 3개';const sig=JSON.stringify(battle.skillBook.progress)+selected+JSON.stringify(battle.skillBook.skills);if(sig!==signature){signature=sig;$('records').replaceChildren();for(const s of battle.skillBook.skills){const d=SkillSystem.describe(battle.skillBook,s),row=document.createElement('p'),b=document.createElement('button');b.textContent=d.name+(s.id===selected?' · 선택됨':'');b.onclick=()=>{selected=s.id;};row.append(b,document.createElement('br'),document.createTextNode(d.text+' · 경험 '+d.masteryXP+' · 유효 사용 '+d.uses+'회'));$('records').append(row);}}requestAnimationFrame(frame);}
reset();requestAnimationFrame(frame);
